CREATE TABLE charge_voids(charge_id TEXT PRIMARY KEY REFERENCES service_charges(id),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 4 AND 500),actor TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TRIGGER void_only_unpaid_account_charge BEFORE INSERT ON charge_voids BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM service_charges q WHERE q.id=NEW.charge_id AND q.customer_id IS NOT NULL AND q.monthly_id IS NULL AND q.total>0 AND (q.stay_id IS NULL OR EXISTS(SELECT 1 FROM stays s WHERE s.id=q.stay_id AND s.state='closed'))) OR EXISTS(SELECT 1 FROM charge_allocations WHERE charge_id=NEW.charge_id) THEN RAISE(ABORT,'OESTE_CONFLICT') END; END;
CREATE TRIGGER allocation_not_voided BEFORE INSERT ON charge_allocations WHEN EXISTS(SELECT 1 FROM charge_voids WHERE charge_id=NEW.charge_id) BEGIN SELECT RAISE(ABORT,'OESTE_CONFLICT'); END;
CREATE TRIGGER immutable_charge_void_update BEFORE UPDATE ON charge_voids BEGIN SELECT RAISE(ABORT,'OESTE_IMMUTABLE_CHARGE'); END;
CREATE TRIGGER immutable_charge_void_delete BEFORE DELETE ON charge_voids WHEN NOT EXISTS(SELECT 1 FROM maintenance_reset_gate g JOIN operations o ON o.id=g.operation_id AND o.kind='delivery-reset' JOIN users u ON u.id=g.actor_id AND u.role='admin' AND u.active=1 WHERE o.user_id=u.id AND EXISTS(SELECT 1 FROM meta WHERE id='sourceKind' AND value='synthetic') AND EXISTS(SELECT 1 FROM meta WHERE id='authority' AND value='cloud-test')) BEGIN SELECT RAISE(ABORT,'OESTE_IMMUTABLE_CHARGE'); END;
